referenceSolutions.python:
def prefixCabinetFirstQualifyingSlip(words, k):
    a=words
    out=[]
    next_nodes=[{}]
    counts=[0]
    for word in a:
        node=0
        for c in word:
            if c not in next_nodes[node]:
                next_nodes[node][c]=len(next_nodes)
                next_nodes.append({})
                counts.append(0)
            node=next_nodes[node][c]
            counts[node]+=1
    for word in a:
        node=0
        s=0
        for c in word:
            node=next_nodes[node][c]
            s+=counts[node]
        out.append(s)
    return next((x for x in out if x>=k),-1)

